import{_ as o,o as a,c as r,a5 as d}from"./chunks/framework.BEZBAInb.js";const h=JSON.parse('{"title":"Logger","description":"","frontmatter":{"title":"Logger","order":4},"headers":[],"relativePath":"zh/latest/tutorial/core/logger.md","filePath":"zh/latest/tutorial/core/logger.md","lastUpdated":1788455378000}'),t={name:"zh/latest/tutorial/core/logger.md"};function c(l,e,n,i,g,s){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="日志器-konadologger" tabindex="-1">日志器 KonadoLogger <a class="header-anchor" href="#日志器-konadologger" aria-label="Permalink to &quot;日志器 KonadoLogger&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>KonadoLogger 是基于Godot Logger实现的日志模块，支持日志级别、日志格式、日志输出、日志文件等功能，用于记录Konado运行时的日志信息。</p><h2 id="日志路径" tabindex="-1">日志路径 <a class="header-anchor" href="#日志路径" aria-label="Permalink to &quot;日志路径&quot;">​</a></h2><p>日志文件逻辑路径为 <code>user://konado_log.log</code>，其实际目录由 Godot 针对当前操作系统和项目名称决定，可通过 <code>OS.get_user_data_dir()</code> 查看。<code>LOG_FILE_PATH</code> 是内置常量；如需改用其他路径，应在维护自定义插件版本时修改该常量。</p><h2 id="屏幕覆盖日志" tabindex="-1">屏幕覆盖日志 <a class="header-anchor" href="#屏幕覆盖日志" aria-label="Permalink to &quot;屏幕覆盖日志&quot;">​</a></h2><p>发生错误时，对话场景会在屏幕上覆盖一个日志窗口，用于显示错误信息并中断游戏运行。普通警告仍会写入日志文件，但不会显示为运行时错误或中断游戏。如果您希望关闭错误覆盖窗口，可以将 <code>KonadoDialogueManager</code> 的 <code>enable_overlay_log</code> 属性设置为 <code>false</code>。</p><h2 id="日志回调" tabindex="-1">日志回调 <a class="header-anchor" href="#日志回调" aria-label="Permalink to &quot;日志回调&quot;">​</a></h2><p><code>KonadoLogger</code> 实例会发出 <code>error_caught(msg)</code> 和 <code>message_caught(message, error)</code> 信号。<code>KonadoDialogueManager</code> 会在进入场景树时创建并向 Godot 注册内部日志器，再使用 <code>error_caught</code> 驱动覆盖日志；它不是全局自动加载对象。自定义日志集成如果另行创建 <code>KonadoLogger</code>，必须使用 <code>OS.add_logger()</code> 注册，并在释放前使用 <code>OS.remove_logger()</code> 注销，避免重复记录或残留无效实例。</p><h2 id="运行时故障" tabindex="-1">运行时故障 <a class="header-anchor" href="#运行时故障" aria-label="Permalink to &quot;运行时故障&quot;">​</a></h2><p>原子指令执行失败时，<code>KonadoDialogueManager</code> 只写入一条最终错误，并发出 <code>runtime_failure_reported(failure)</code> 信号。<code>failure</code> 包含稳定错误码、具体操作、相关资源、底层原因、源码路径与行号、指令 ID、操作码和程序位置，适合接入崩溃上报或自定义调试界面。<code>runtime_failed(message, instruction_id, source_line)</code> 作为简化接口保留。</p>',11)])])}const u=o(t,[["render",c]]);export{h as __pageData,u as default};
